<script>
(() => {
    if (window.carbTemperCountdownTimer) return;

    const updateCountdown = () => {
        const root = document.getElementById('carbTemperRoot');
        const label = document.getElementById('carbCountdown');
        if (!root || !label) return;

        const updatedAt = Number(root.dataset.lastUpdated || 0);
        const elapsed = Math.floor(Date.now() / 1000) - updatedAt;
        const remaining = Math.max(0, 600 - elapsed);
        const minutes = Math.floor(remaining / 60);
        const seconds = String(remaining % 60).padStart(2, '0');
        label.textContent = remaining > 0 ? minutes + ':' + seconds : 'memuat...';
    };

    updateCountdown();
    window.carbTemperCountdownTimer = window.setInterval(updateCountdown, 1000);
})();
</script>
